// CONTRÔLE D'INTÉGRITÉ DU WEBHOOK APPWRITE
//
// n8n.kernelforge.codes répond déjà publiquement en HTTP 200 (vérifié le
// 2026-09-25 : /healthz ok, et POST /webhook/__probe__ → le 404 typique de n8n,
// derrière Caddy). Un webhook laissé sans vérification serait donc, sur
// Internet, un bouton « envoyer un email de bienvenue à l'adresse que je choisis ».
//
// Appwrite ne peut pas poser d'en-tête d'authentification arbitraire : il signe.
// La doc annonce « X-Appwrite-Webhook-Signature : HMAC-SHA1 du corps » et
// précise de concaténer l'URL du webhook avant le corps. D'où WEBHOOK_URL
// ci-dessous, qui doit être strictement identique à celui saisi dans la console.
//
// Le corps doit être celui REÇU, octet pour octet : d'où options.rawBody sur le
// nœud Webhook. Sans ça n8n re-sérialise le JSON, les espaces changent, et le
// HMAC ne collera jamais. Symptôme attendu : 403 permanent alors que tout le
// reste est juste — c'est cette erreur qu'il ne faut pas chercher deux jours.

const crypto = require('crypto')

const WEBHOOK_URL = 'https://n8n.kernelforge.codes/webhook/appwrite-users'

// Fautif par construction : sans secret, on n'envoie rien. Une bienvenue qui
// part quand même sans contrôle serait pire qu'un silence.
const secret = (typeof $env !== 'undefined' && $env.APPWRITE_WEBHOOK_SECRET) ? String($env.APPWRITE_WEBHOOK_SECRET) : ''
if (!secret) {
  throw new Error('APPWRITE_WEBHOOK_SECRET absent côté n8n : livraison refusée. Définir la variable d’environnement, et laisser N8N_BLOCK_ENV_ACCESS_IN_NODE à false pour que $env soit lisible dans les expressions.')
}

const item = $input.first().json || {}
const headers = item.headers || {}
const raw = typeof item.rawBody === 'string' ? item.rawBody : JSON.stringify(item.body ?? {})
const received = String(headers['x-appwrite-webhook-signature'] || '')
const expected = crypto.createHmac('sha1', secret).update(WEBHOOK_URL + raw).digest('hex')

// timingSafeEqual lève si les deux tampons n'ont pas la même longueur.
const candidate = Buffer.from(received.length === expected.length ? received : '0'.repeat(expected.length))
if (received.length !== expected.length || !crypto.timingSafeEqual(candidate, Buffer.from(expected))) {
  throw new Error('SIGNATURE_REJETEE : HMAC-SHA1 non concordant, livraison refusée.')
}

let payload = item.body
if (typeof payload === 'string') { try { payload = JSON.parse(payload) } catch { payload = {} } }
payload = payload || {}

// Forme exacte du payload d'un événement de plateforme : la doc renvoie au
// modèle « User Object » sans garantir ni l'enveloppe ni l'en-tête d'événement.
// On accepte donc les deux formes connues. Le premier envoi réel se contrôle sur
// la sortie du nœud Webhook dans la liste des exécutions, avant d'être serré.
const event = String(headers['x-appwrite-event'] || payload.event || '')
const user = payload.user || payload.payload || payload
if (event && !/^users\.create$/i.test(event)) return []

const email = String(user.email || '').trim()
const name = String(user.name || user.username || '').trim()
const userId = String(user.$id || user.userId || '').trim()
if (!email || !userId) return []

// Les comptes de seed et de QA vivent tous sur des TLD réservés, non livrables
// par définition protocolaire (RFC 6761 / 7505) : .test, .local, .invalid.
// Vérifié dans scripts/seed-accounts.mjs — administration.ict4d@uniflow.test,
// qa@example.invalid, qr-delegate-…@test.uniflow.local. Une règle sur le TLD
// couvre aussi les seeds que tu écriras plus tard, sans liste à maintenir.
const tld = email.slice(email.lastIndexOf('.')).toLowerCase()
if (['.test', '.local', '.invalid'].includes(tld)) return []
if (/@example\./i.test(email)) return []

// Appwrite rejoue une livraison qui n'a pas répondu à temps : sans déduplication
// un étudiant reçoit deux ou trois bienvenues. Les 800 derniers identifiants
// tiennent en données statiques du workflow — pas de base externe, pas de secret.
const store = $getStaticData() || {}
const seen = Array.isArray(store.welcomed) ? store.welcomed : []
if (seen.includes(userId)) return []
seen.push(userId)
$setStaticData({ welcomed: seen.slice(-800) })

return [{ json: { email, name, userId, event: event || 'users.create' } }]

// Le texte du bienvenue est un GABARIT, pas une génération de modèle.
//
// Ce message énonce des règles du produit : qui s'inscrit librement, qui crée
// les comptes enseignant et administration, comment se règlent les offres
// payantes. Un modèle peut en reformuler une à l'envers, et cette reformulation
// engage KERNEL FORGE. Gemini 3.1 Flash-Lite garde son rôle là où il sert : la
// conversation, dans l'application (workflow « Uni · Passerelle assistant »).
//
// Ce que le payload ne dit PAS : users.create ne porte que le compte — email,
// nom, $id. Ni le rôle, ni l'université, ni la filière : elles sont dans les
// documents Appwrite, et n8n n'a volontairement aucune clé pour les relire. D'où
// un message qui ne promet rien de précis sur le rôle, et qui renvoie vers la
// complétion du profil — ce qui est de toute façon le vrai blocage, parce que
// sans filière ET niveau UniFlow n'affiche aucun emploi du temps (la branche
// `scheduleScope: 'none'` de `describeSchedule`, src/lib/assistant.js).

const user = $input.first().json || {}
const firstName = String(user.name || '').trim().split(/\s+/)[0] || ''
const salutation = firstName ? `Bonjour ${firstName},` : 'Bonjour,'
const sujet = firstName ? `${firstName}, ton compte UniFlow est ouvert` : 'Ton compte UniFlow est ouvert'

return [{
  json: {
    subject: sujet,
    preheader: 'Emploi du temps, notes, présences — et Uni, l’assistant intégré.',
    title: 'Ton compte UniFlow est prêt',
    salutation: `${salutation} ton compte est créé sur UniFlow, la plateforme académique de KERNEL FORGE (Université de Yaoundé I, Faculté des Sciences).`,
    paragraphs: [
      'Une chose tout de suite : ouvre ton profil et renseigne ta filière et ton niveau. UniFlow affiche l’emploi du temps par filière ET par niveau ; tant que ces deux champs manquent, ni ton emploi du temps ni Uni ne peuvent te dire quel cours tu as aujourd’hui.',
      'Dans l’application, tu trouveras aussi l’assistant Uni — la petite mascotte, en bas à droite. Il connaît les écrans, les règles d’inscription et tes séances du jour. Il répond en français, et il ne modifie rien à ta place.',
    ],
    bullets: [
      'Emploi du temps, unités d’enseignement, devoirs, notes et présences par QR code',
      'Bibliothèque de documents, messagerie, forum et notifications',
      'Espace personnel pour les comptes indépendants',
      'Sur mobile et sur ordinateur, les données déjà synchronisées restent lisibles hors ligne',
    ],
    cta: { label: 'Ouvrir UniFlow', url: 'https://uniflow.kernelforge.codes/#/login' },
    note: 'Compte étudiant : l’inscription est libre. Les comptes enseignant, délégué et administration sont créés par l’administration de ton université, et les comptes administration par l’administrateur de la plateforme. Les offres payantes se règlent par WhatsApp (+237 6 57 63 56 44), jamais par carte dans l’application.',
  },
}]
